import{_ as a,a as e}from"./chunks/console-dashboard.BS-NHkp_.js";import{_ as o}from"./chunks/console-tenants.DGEJUwWF.js";import{_ as r,o as n,c as i,a3 as s}from"./chunks/framework.DhF4LrUq.js";const w=JSON.parse('{"title":"Platform Operator quickstart","description":"Quickstart for platform operators — the team that runs the ShipperDog instance itself. Organization onboarding, instance health, cross-tenant operations, and break-glass.","frontmatter":{"description":"Quickstart for platform operators — the team that runs the ShipperDog instance itself. Organization onboarding, instance health, cross-tenant operations, and break-glass."},"headers":[],"relativePath":"roles/platform-operator.md","filePath":"roles/platform-operator.md"}'),h={name:"roles/platform-operator.md"};function l(d,t,p,c,g,u){return n(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="platform-operator-quickstart" tabindex="-1">Platform Operator quickstart <a class="header-anchor" href="#platform-operator-quickstart" aria-label="Permalink to &quot;Platform Operator quickstart&quot;">​</a></h1><h2 id="who-you-are" tabindex="-1">Who you are <a class="header-anchor" href="#who-you-are" aria-label="Permalink to &quot;Who you are&quot;">​</a></h2><p>You run the ShipperDog instance itself — the person (or team) ShristiLabs or your own operations group trusts with the platform as a whole. Your account carries the <strong>platform administrator flag</strong> (the <code>platform_admin</code> system role): it is set on your user account directly, not granted through an organization membership, and it works across every organization on the instance. You onboard new organizations, watch instance health, step into cross-tenant situations no one else can reach, and hold the break-glass keys. If you also hold a role inside an organization, treat that as a separate track: work one persona per session and pick the <a href="/shipperdog/snapshot/roles/org-admin">Organization Admin</a> guide when you are wearing that hat.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><p>Your account holds <strong>every permission in the catalog</strong> — nothing in the product is closed to you. In practice the platform-operator surface is:</p><ul><li><strong>Organizations</strong> — create organizations and keep their configuration current; deactivate one to strip every role and resource access its members hold, in one move.</li><li><strong>Cross-tenant operations</strong> — reach into any organization&#39;s tenants for administrative work. Reads stay scoped to the tenant you opened; your cross-tenant writes are always recorded in the audit trail as explicit cross-tenant access events.</li><li><strong>Inspection and audit</strong> — read the platform audit trail and ask the authorization engine to explain any access decision (which layer of the chain allowed or denied it, and why) for any subject.</li><li><strong>Break-glass</strong> — override a blocking quality gate, acknowledge a policy hold, or reassign the last unreachable administrator. One rule binds even you: an organization always keeps at least one Organization Administrator — the last one cannot be demoted or removed, by anyone.</li></ul><p>Everything you do is audited. The platform administrator flag is an operations tool, not a daily-driver role; most work inside an organization belongs to the roles that own it.</p><h2 id="first-15-minutes" tabindex="-1">First 15 minutes <a class="header-anchor" href="#first-15-minutes" aria-label="Permalink to &quot;First 15 minutes&quot;">​</a></h2><p>The screenshots come from the locally running development stack with its seeded demo world — what you see here is what you will see there.</p><ol><li><p><strong>Sign in to the Console.</strong> Use your platform account. The Console treats you like any other member for sign-in; your flag applies after.</p><p><img src="'+a+'" alt="The Console login page"></p></li><li><p><strong>Read the organization dashboard.</strong> You land on the dashboard of an organization you belong to: the counts, per-application release health, and the pending-actions panel. For instance-wide health this is your fastest single glance — check that active releases and pending approvals look sane.</p><p><img src="'+e+'" alt="The organization dashboard"></p></li><li><p><strong>Open Tenants for a cross-tenant check.</strong> The tenants listing is your cross-organization rosters view: each row opens member management, devices, and the tenant dashboard. This is where &quot;something is wrong in a customer tenant&quot; starts.</p><p><img src="'+o+'" alt="The tenants listing"></p></li><li><p><strong>Onboard a new organization.</strong> Creating organizations is an API-level operation today (the Console renders organizations, it does not create them): <code>POST /api/v1/organizations</code> with your platform credentials, then invite the first Organization Administrator into it. The step-by-step guide lands with the console how-tos — <a href="/shipperdog/snapshot/how-to/console/orgs">Onboard an organization</a>.</p></li><li><p><strong>Know your break-glass rules before you need them.</strong> Gate overrides and policy acknowledgements demand a written reason and land in the audit trail with your name on them. Read <a href="/shipperdog/snapshot/concepts/approvals-gates">approvals and gates</a> so the first time you use that authority is not during an incident.</p></li></ol><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><p>Hand-off task list:</p><ul><li>[ ] Read <a href="/shipperdog/snapshot/concepts/architecture">architecture</a> for how the surfaces fit together</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/tenancy-isolation">tenancy and isolation</a> — what your cross-tenant authority does and does not touch</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/authorization">authorization</a> for the decision chain your inspection queries walk</li><li>[ ] Bookmark the how-tos as they land: <a href="/shipperdog/snapshot/how-to/console/orgs">onboard an organization</a>, <a href="/shipperdog/snapshot/how-to/console/audit-log">audit log</a></li><li>[ ] Operations depth (deployment, infrastructure) lives in the developer docs: <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/deployment.md" target="_blank" rel="noreferrer">deployment</a></li></ul>',13)])])}const b=r(h,[["render",l]]);export{w as __pageData,b as default};
